// The keys are generated in a worker, because generating the 4096-bit RSA keys blocks the main thread in some browsers and makes rendering stutter.

// Values are inlined because of the string generated by the toString call will not have the same context. It is not written in a string in order to allow the build tool to minify and post-process the function's contents.

export const USER_KEY_GENERATOR =
	"self.addEventListener('message'," +
	(() => {
		Promise.all([
			crypto.subtle.generateKey(
				{
					hash: "SHA-256",
					modulusLength: 4096,
					name: "RSA-OAEP",
					publicExponent: new Uint8Array([1, 0, 1]),
				},
				false,
				["encrypt", "decrypt"],
			),
			crypto.subtle.generateKey(
				{
					hash: "SHA-256",
					modulusLength: 4096,
					name: "RSASSA-PKCS1-v1_5",
					publicExponent: new Uint8Array([1, 0, 1]),
				},
				false,
				["sign", "verify"],
			),
			crypto.subtle.generateKey(
				{
					name: "ECDH",
					namedCurve: "P-256",
				},
				false,
				["deriveBits"],
			),
		])
			.then(([encryptKeys, signKeys, exchangeKeys]) =>
				Promise.all([
					crypto.subtle.exportKey("spki", encryptKeys.publicKey),
					crypto.subtle.exportKey("spki", signKeys.publicKey),
					crypto.subtle.exportKey("raw", exchangeKeys.publicKey),
				]).then(([publicEncryptKey, publicSignKey, publicExchangeKey]) => {
					self.postMessage({
						success: true,
						encryptKeys,
						exchangeKeys,
						publicEncryptKey,
						publicExchangeKey,
						publicSignKey,
						signKeys,
					});
				}),
			)
			.catch((error) => {
				self.postMessage({
					success: false,
					error: error.message,
				});
			});
	}).toString() +
	")";

export const SHARED_KEY_GENERATOR =
	"self.addEventListener('message'," +
	(() => {
		crypto.subtle
			.generateKey(
				{
					length: 256,
					name: "AES-GCM",
				},
				true,
				["encrypt", "decrypt"],
			)
			.then((sharedKey) => {
				self.postMessage({
					success: true,
					sharedKey,
				});
			})
			.catch((error) => {
				self.postMessage({
					success: false,
					error: error.message,
				});
			});
	}).toString() +
	")";
